const SEED = {"M01":{"scores":{"hierarchy":7,"density":7,"color":6,"craft":6,"states":4,"sideBySide":5,"functionality":3,"completeness":6},"verdict":"not_wowed","blindPick":"A","blindMapping":"spec-based audit, no live blind comparison","kitstaksWins":false,"fixes":["src/components/orders/bulk/order-job-modal.tsx (useEffect at ~L127-155): stop calling POST /api/ops/allocate when the modal mounts. Allocate only after the user clicks Create Job or Select Job, inside the same server transaction as job creation. If allocation must run up front, roll it back when the user clicks Cancel or X.","src/components/orders/bulk/order-job-modal.tsx (~L139-150): treat an order the allocator leaves in Shortage, or with allocatedQuantity < ordered, as failed. Add it to `fails` with the shortage message so the banner reads '0 of 1 order is allocated' and the FailureList names the short SKU. Never show 'allocated and ready' while the row is Shortage with 0 allocated.","Order code sequence (sequences.peek used by src/components/orders/wizard/step-details.tsx and /api/orders/code-check): skip codes that already exist. Loop the peek until code-check returns unique, or seed the sequence from MAX(code). The 'auto generated' regenerate link must return a new unique code, not the same SO010873.","src/components/orders/wizard/order-summary.tsx L32-33 and src/components/ui/progress-ring.tsx: the ring's centered percent label overlaps the absolutely positioned Truck icon, and the percent also repeats in the <p> beside it. Pass a prop that hides the inner label (e.g. showValue={false}) or remove the Truck overlay. Also compute percent as completed steps / 6 (0% at start, as in Logiwa), not 25% on first paint.","src/components/orders/detail/order-detail-page.tsx L88-95 and 169: while usePermissionSet() is still loading, render a skeleton or a neutral disabled Save (aria-busy) instead of the copy 'You don't have permission to edit shipment orders'. An Owner/admin with fulfillment.shipment_orders.edit currently sees that denial plus every field disabled until hydration finishes, 10-45s on this dev server.","src/components/orders/detail/order-detail-page.tsx and order-form-model.ts valuesFromDetail: the Order type select renders empty before hydration while the Summary card says 'D2C Order'. Seed the select's options from the server detail (detail.orderTypeName) so the SSR value is never blank.","src/components/orders/orders-list-page.tsx: render the page-header actions (Import, Create shipment order) and the bulk toolbar during the grid's loading state. Today they are absent until /api/orders resolves, 6-25s. Only the grid body should skeleton.","Server /api/orders?view=backlog (src/server/repositories/orders*.ts): 6.4s for 42 rows and 10s for /api/orders?view=shipped (413 rows), timed by fetch in the page. Profile the N+1 behind the per-row SKU/tags/job/customer joins; batch into single queries and add indexes on (status, warehouse_id, order_date). Also stop the duplicate request: each first load issues /api/orders, /options, /grid-prefs and /saved-views twice (first set ERR_ABORTED).","DataGrid (src/components/grid/data-grid.tsx): show an in-grid progress bar or dimmed rows while a refetch for a new filter, sort or search is in flight. Right now stale rows and the stale 'Total: 42' stay on screen for ~10s after Apply, with no busy indicator.","src/components/orders/wizard/step-details.tsx client combobox: show 'Loading clients...' with a spinner while options load. It currently shows 'No results' for ~5s after a warehouse is picked. Also stop clearing Order type when the warehouse or client changes (it reset from D2C Order to blank twice).","src/components/orders/wizard/step-products.tsx product-search-add: disable the + button and show a spinner per row while the add request is in flight, and debounce repeat clicks. The add takes 3-5s with no feedback, which produced an unintended qty 2 on APX-TEE-BLK-L. Show the ATP value in the search dropdown rows; it shows 'ATP —' there even though the added lines show 348/322.","Change log writer for order line creation (orders.createOrder in src/server/repositories/orders*.ts): each line's 'Quantity is modified. 0 --> N' entry is written twice (4:22:15 and 4:22:16). Write it once, using Logiwa's '<SKU> -> Shipment Order Line is created.' message. Also log address verification ('Address line 2 was merged into address line 1.') as a change-log entry.","Order detail rail (src/components/orders/detail/order-detail-rail.tsx): after a background status change (Open -> Ready to Pick, Job005279), the Summary still showed Open / 'No job assigned' / Last update 4:22:16 while the Activity feed on the same page already showed the job. Invalidate or poll the detail query together with the activity feed so the page never contradicts itself.","Gating in src/components/orders/bulk/order-eligibility.ts: Ship order is disabled for both Open and Ready to Pick orders, but Logiwa enables Ship Order for both. Create label is disabled for an Open order with no visible reason. Every disabled bulk menuitem needs a DisabledReason tooltip with the exact reason, e.g. 'No carrier service set on SO010873'.","Empty state (src/components/orders/orders-list-page.tsx): when the backlog has zero results, render the two Logiwa CTA cards below 'Could not find any shipment order': 'No products? Create products before creating a shipment order.' -> /products and 'OR You can create shipment orders here.' -> /orders/new. Only the text line renders today.","Dark-mode status pills (status-pill tokens used by src/lib/grid-defs/orders/shipment-orders.ts columns): Shortage (#F7E9E4/#A13406), Ready to Ship (#DFCEF5/#621DB8) and On Hold (#D7D9DD/#394357) keep light Logiwa backgrounds in dark mode. Ready to Pick is rgb(46,92,230) text on a 10% tint over the navy surface, which is under 3:1 contrast. Define --status-*-bg/-fg tokens per theme so every pill uses the same tinted dark treatment with >= 4.5:1 text contrast.","Shipped & Canceled grid: the cancelled order KS-E2E-SO-1 shows an Actual shipment date (11/06/2026 9:30 AM) equal to its cancel date. Leave shippedAt null for Cancelled orders. Let the default chip include cancellations by OR-ing cancelDate, or add a second 'Cancel date: Last 7 days' chip.","Create RMA (order-bulk-menus.tsx createRma): show a pending state on the button (spinner, disabled) during router.push. The navigation took ~15s with no feedback.","Copy: 'Add Note' (order detail NotesPanel), 'Custom Fields' / 'Create Custom Field' (step-other.tsx) and the 'Packing Slip (copy)' template label are Title Case or test junk. Use sentence case ('Add note', 'Custom fields', 'Create custom field') and rename or hide the duplicate packing-slip template. The return-address dropdown lists '1400 W Fulton Market, Chicago' twice; dedupe it or add the address name.","Order code column (src/components/orders/orders-columns.tsx): widen it to fit 16+ character codes, or add a title tooltip. KS-TEST-M01-SO-1 truncates to 'KS-TEST-M01-...'.","Accessibility: the tag chip buttons in the Tag popover and the two Billing address radios (step-customer.tsx) have no accessible names. Add aria-label or associated labels."],"functional_failures":["Opening a dialog mutates data: go to /orders, tick SO010873 (status Open), then Warehouse ops > Picking / job operations. The modal immediately POSTs /api/ops/allocate. Click Cancel. The order is now permanently 'Shortage' (GET /api/orders/SO010873 -> status Shortage, line alloc 0) even though no job was created.","Picking/job modal reports success incorrectly: in the same repro, the modal banner says '1 of 1 order is allocated and ready for a picking job' while the row behind it has just flipped to Shortage with 0 allocated.","The auto-generated order code collides: open /orders/new and click Next step with nothing filled. Order code is pre-filled 'SO010873' and shows 'Order code SO010873 already exists'. Clicking 'auto generated' (regenerate) returns the same SO010873. A user cannot create an order with the default code.","Pre-hydration permission denial: as admin@kitstak.io (role admin, userType Owner, /api/me lists fulfillment.shipment_orders.edit), open /orders/KS-TEST-M01-SO-1. For 10-45s the rail says 'You don't have permission to edit shipment orders', Save shipment order is disabled with that tooltip, all fields are disabled, and Order type is blank.","Grid chrome missing while loading: open /orders fresh. For 6-25s only skeleton rows render; the Import and Create shipment order header buttons and the Label / Warehouse ops / Print / Delete / Tag toolbar are absent and the page-size select is empty. The first visit in this run stayed on the skeleton indefinitely until a manual reload.","Backlog API latency: in the page, fetch('/api/orders?view=backlog') took 6.4s for 42 rows and fetch('/api/orders?view=shipped') took 10.0s. Applying the Status=Open filter kept stale rows and 'Total: 42' on screen ~10s with no busy indicator before showing Total 21.","Wizard client select shows a false empty state: on /orders/new pick Warehouse 'MLT1 - Main Fulfillment' and open Client right away. It shows 'No results' for ~5s, then the list appears. Order type also resets to blank after the warehouse or client changes.","Duplicate line add with no feedback: on wizard step 3, search 'APX-TEE-BLK' and press + on APX-TEE-BLK-L. There is no spinner or disabled state for 3-5s, so a second press adds again and the line becomes qty 2 ($72.00 total instead of $48.00). The search dropdown shows 'ATP —' for every result.","Change log duplicates: create KS-TEST-M01-SO-1 with 2 lines, then Show change log. Each line has two identical entries, 'APX-TEE-BLK-L -> Quantity is modified. 0 --> 2', at 4:22:15 and 4:22:16. There is no 'Shipment Order Line is created' entry and no address-normalization entry.","The detail page contradicts itself: after the order was moved to Ready to Pick / Job005279 at 4:24:41, the open detail page's Summary still read 'Open', 'No job assigned', 'Last update 4:22:16' while its Activity feed listed 'Status is modified. Open --> Ready to Pick'. Saving then returned PATCH 409; the conflict banner only fixed it after Reload.","Ship order is never enabled: tick an Open order (SO010873) or open Other actions on the Ready to Pick order KS-TEST-M01-SO-1. Ship order is disabled with no reason shown. Create label is disabled with no reason for the Open order.","Backlog empty state is incomplete: open /orders?q=ZZZNOPE. Only 'Could not find any shipment order / Try changing the filters or search term' renders; the two CTA cards required by the spec and checklist are missing.","Cancelled order shows a ship date: open /orders/shipped (default chip Actual shipment date Last 7 days). Cancelled row KS-E2E-SO-1 shows Actual shipment date 11/06/2026 9:30 AM, identical to its Cancel date.","Create RMA has no feedback: on /orders/shipped tick SO010848 (Shipped) and click Create RMA. Nothing visible happens for ~10-15s, then it navigates to /orders/returns/new?orderIds=... The button shows no pending state.","Dark-mode contrast: with the dark color scheme, open /orders. The 'Ready to Pick' pill is rgb(46,92,230) text on a 10% blue tint over the navy surface, under 3:1 contrast. Shortage, Ready to Ship and On Hold pills keep light Logiwa backgrounds (#F7E9E4, #DFCEF5, #D7D9DD) and read as light-only surfaces.","Progress ring overlap: on /orders/new the Order status ring draws its '25%' label on top of the truck icon, and '25%' repeats beside it. It shows 25% before any field is filled, 75% at step 3 with no products, and 100% with the label overlapping the icon on the detail page.","Tags column is not sortable: on /orders the TAGS header has no sort button, while every other column header has 'Click to sort'."],"logiwa_wins":["Per spec, Logiwa's Ship Order is enabled for Open and Ready to Pick orders, with a confirm table. KitStaks disables Ship order for both and gives no reason.","Per spec, Logiwa's Create Job wizard allocates only as part of creating or merging the job. KitStaks allocates as soon as the modal opens, mutates status on Cancel, and reports false success.","Per spec, Logiwa auto-fills the next unique order code (e.g. SO0008) with a working regenerate link. KitStaks pre-fills a code that already exists and regenerate returns the same code.","Per spec, Logiwa's empty state has the two CTA cards ('No products? Create products...' and 'OR You can create shipment orders here'). KitStaks shows only the text line.","Per spec, Logiwa's progress ring is a clean 0-100% (20% per step) with a truck icon. KitStaks overlaps the percent text with the icon, duplicates it, and starts at 25%.","Per spec, Logiwa's change log writes '<SKU> -> Shipment Order Line is created.' once per line and logs address-verification notes. KitStaks double-writes quantity entries and omits the line-created and verification entries.","Per spec, Logiwa's product search rows show live availability. KitStaks' search dropdown shows 'ATP —' for every SKU.","Per spec, Logiwa's Shipped & Canceled tab shows CANCEL DATE separately from ACTUAL SHIPMENT DATE. KitStaks fills Actual shipment date on cancelled orders.","Per spec, Logiwa's status pills use one consistent palette. KitStaks mixes light Logiwa pill backgrounds with themed translucent pills in dark mode, and Ready to Pick fails contrast.","Per spec, Logiwa's header actions and toolbar render immediately with the grid. KitStaks hides Import, Create and the bulk toolbar until the 6-25s data fetch finishes."]},"M02":{"scores":{"hierarchy":8,"density":6,"color":6,"craft":7,"states":7,"sideBySide":7,"functionality":6,"completeness":7},"verdict":"not_wowed","blindPick":"A","blindMapping":"spec-based audit, no live blind comparison","kitstaksWins":false,"fixes":["src/server/repositories/end-of-day.ts plus the label create/void hooks in src/server/repositories/shipping*.ts: compute EOD totalPackages from live shipments (COUNT of Active labels where manifestId = row.id) instead of a stored counter. Backfill manifestId for the 32 shipments that have manifestId=null; for example the 2026-11-06 MLT1 rows should point at manifest de5950cb. Add a unit test in tests/unit/shipping asserting that the EOD total equals the active label count for every manifest.","src/lib/status-colors.ts TONES.teal: fg #0F8C7A on #D0F3EE measures 3.51:1, below WCAG AA, even though the comment says it was darkened. Change fg to #0B6E60 or darker (at least 4.5:1). Re-verify every tone with a contrast unit test.","src/components/ui/status-pill.tsx (lines 30, 63, 79): pills use inline style={{backgroundColor: tone.bg, color: tone.fg}} with light-only hex values, so in dark mode every pill is a pastel chip on the #0F1B2E surface. Add a dark variant per tone in status-colors.ts (e.g. bg rgba(fg,.18), fg a lighter tint) and switch on [data-theme=dark], or move the tones to CSS variables that are redefined under :root[data-theme=dark].","src/components/shipping/end-of-day-page.tsx Total package link uses text-primary (#e8344f), which is 4.14:1 on the dark grid surface rgb(15,27,46). In dark mode use a lighter primary (e.g. #FF6B7F) for link text, or use a neutral link color in data cells.","src/components/shipping/end-of-day-page.tsx Ship date cell: formatDate renders '11/9/2026' while Close date renders '11/06/2026 10:33 AM'. Use the same zero-padded MM/DD/YYYY formatter for both columns.","src/components/shipping/end-of-day-page.tsx Ship from cell renders '{warehouseCode} · {shipFrom}', and shipFrom already contains the code, giving 'MLT1 · MLT1 - Main Fulfillment'. Render shipFrom only, or code plus the warehouse name without the prefix.","Seed/data (carrier connections): UPS and USPS manifests for MLT1 share the same prefix 'KSB-MLT1', so PREFIX can't tell carrier accounts apart, which is the column's only job. Give each carrier connection a distinct account prefix (e.g. KSB-UPS-MLT1, KSB-USPS-MLT1).","Seed: closed manifests show a close date 3 days after the ship date (ship 10/27, closed 10/30 10:15 AM). EOD closes the same evening. Set the seeded closeDate to the shipDate at about 17:30 local.","Seed + src/components/shipping/shipments-columns.tsx: Inventory location is null on 470/470 rows. Insurance type, Scheduled pickup date, Actual pickup date, Inventory parent LPN and External reference are null on every row. Populate realistic values in the seed (packing location, LP parent for multi-package orders, pickup dates on closed manifests), or hide those columns by default.","Seed for /api/shipment-plans/lps: the Shipment plan LPs tab returns total 0 across all data. Seed LP rows for the shipped and in-progress plans (SP000041-44) so the tab and its 20 columns aren't an empty grid.","src/components/shipment-plans/plan-order-picker.tsx COLUMNS: add the spec's WAREHOUSE, AGE (days since createdAt) and TAGS columns, and make SKU sortable.","src/components/shipping/shipments-columns.tsx: Products and Customer address are sortable:false. Logiwa headers are all sortable, so enable server sort on both (sort by the first SKU and by ship_city/state).","Copy: src/components/layout/page-header tabs and breadcrumb show Title Case ('End Of The Day', 'Carrier Shipment Details') while the H1 is sentence case ('End of the day'). Change tab and breadcrumb labels to sentence case ('End of the day', 'Carrier shipment details').","src/components/shipping/shipments-columns.tsx: rename 'Is allow Saturday delivery' to 'Saturday delivery'. The label was copied word for word from Logiwa's awkward column name.","Shipment plan state machine (src/server/state-machines shipmentPlan): Open -> In Progress is one-way, there is no Open edit path back, and Delete is Open-only. A plan moved to In Progress by mistake can only be Cancelled and stays in the list forever. Allow In Progress -> Open while no order has been loaded, or allow deleting In Progress plans with zero loaded orders.","src/components/shipment-plans/plan-drawer-steps.tsx and createPlan: Expected total weight/volume stay 0 when a plan is created or PATCHed with orders unless the client called /estimate (KS-E2E-SP-1 has 2 orders and weight 0). Compute the estimate server-side in createPlan/updatePlan when the fields are omitted or 0.","src/app/(app)/loading.tsx + streaming: the pages depend on Suspense reveal and React Query in ways that left /shipments stuck on the skeleton (empty main) in a background tab until $RV was forced. Check that the shipments list renders without depending on requestAnimationFrame-driven reveal, e.g. by rendering the client grid outside the streamed Suspense boundary."],"functional_failures":["EOD totals don't reconcile with labels: GET /api/end-of-day returns manifest de5950cb (KSB-MLT1, ship date 2026-11-06, MLT1) with totalPackages=20 and voidedPackages=1. GET /api/shipments?ps=500 has only 2 labels with manifestId=de5950cb, while 23 MLT1 labels were created on 2026-11-06 (22 Active, 1 Voided), 21 of them with manifestId=null. Repro: open /shipments/end-of-day, find the 11/6/2026 KSB-MLT1 row (Total package 20), click the 20. The drilldown to /shipments lists 23 labels, which matches neither 20 nor 19 net. In total 32 of 470 labels have no manifest. This fails the 'Label to manifest' and 'Void' acceptance criteria.","Dark mode pills are light-only: open /shipments/end-of-day, set user menu > Appearance > Dark. Every Open/Closed pill keeps its light pastel background (Open: rgb(208,243,238) bg, rgb(15,140,122) text) on the dark navy grid. The colors come from inline styles in status-pill.tsx and do not adapt to the theme.","Contrast failure on the EOD Open pill: the teal tone #0F8C7A on #D0F3EE is 3.51:1 at 11px in both themes (below the 4.5:1 AA minimum). Repro: /shipments/end-of-day, inspect any 'Open' status pill.","Dark mode Total package links fail contrast: on /shipments/end-of-day in Dark, the Total package numbers render #e8344f on rgb(15,27,46) at 4.14:1.","Shipment plan LPs tab is empty: GET /api/shipment-plans/lps returns {data:[],total:0} for the whole tenant, so /shipment-plans/lps can only ever show an empty grid. The Plan LPs tab can't be verified.","Stuck plan: POST /api/shipment-plans {code:'KS-TEST-SP-R1', warehouse MLT1, status Open} -> 201. POST /api/shipment-plans/{id}/status {status:'In Progress'} -> ok. Afterwards nextStatuses is ['Loading Started','Cancelled'] and deleteBlockedReason is 'Only Open shipment plans can be deleted'. A mistaken status change can't be undone, and the record can only be cancelled; it stays in the list forever (KS-TEST-SP-R1 is now Cancelled).","Expected weight not computed server-side: PATCH /api/shipment-plans/{id} with orderIds=[SO010700 (12.8 oz)] persists orderCount=1 but expectedTotalWeight stays 0. KS-E2E-SP-1 with 2 orders also shows weight 0 and volume 0, against the build plan's 'computed from the orders' requirement.","Initial render hangs on the skeleton: navigating a fresh tab to /shipments in the built-in browser rendered only the loading skeleton (main textContent empty after more than 10s) until React's streamed Suspense reveal ($RV) was forced manually. Then End of the day showed 'Loading manifests' with zero rows for well over 10s, even though /api/end-of-day answered in 0.23s via curl. This may come from the hidden-pane environment, but the page doesn't recover on its own. Inline edits, the wizard and the void flow could not be exercised in the UI for this reason; they were checked through the API and the code instead."],"logiwa_wins":["Per spec, Logiwa's EOD prefix is the carrier account prefix and is unique per carrier account. KitStaks uses 'KSB-MLT1' for both UPS and USPS, so the Prefix column doesn't identify the account.","Per spec, the Add Order(s) drawer in Logiwa's Shipment Plan shows ORDER TYPE, STORE, WAREHOUSE, CREATED DATE, AGE, SKU, CLIENT, TAGS, CUSTOMER and TOTAL QUANTITY. KitStaks' plan-order-picker lacks WAREHOUSE, AGE and TAGS.","Per spec, all Logiwa column headers are sortable. KitStaks Carrier shipment details has Products and Customer address unsortable.","Per spec, Logiwa's Shipment Plan LPs tab carries LP-level data (LP, Parent LPN, LP actual weight/volume). KitStaks has no LP rows at all, so the tab is empty.","Per spec, Logiwa's Carrier Shipment Details shows Inventory location (e.g. 'Packing') on every row. KitStaks has it null on 470/470 rows, and Insurance, Pickup dates, Parent LPN and External reference are also always empty.","Per spec, Logiwa's Shipment Plan Create allows any Status* value. KitStaks restricts new plans to Open/In Progress and has no way back to Open or to delete once a plan leaves Open, which is less forgiving for planners."]},"M03":{"scores":{"hierarchy":7,"density":6,"color":5,"craft":6,"states":7,"sideBySide":7,"functionality":7,"completeness":7},"verdict":"not_wowed","blindPick":"A","blindMapping":"spec-based audit, no live blind comparison","kitstaksWins":false,"fixes":["src/components/wave-rules/wave-rule-steps.tsx:317 (schedule day chips): replace the hardcoded `border-[#17874D] bg-[#D3F0E3] text-[#17874D]` with tokens (`border-success bg-success-soft text-success`) and define success-soft in the :root and [data-theme=dark] tokens. In dark mode the active 'Monday x' chip currently shows as a pale-mint light-only surface.","Remove every hardcoded light-palette pill in the module and use StatusPill/token classes instead: jobs-list-page.tsx:25 LabelPill (#D3F0E3/#FFF3D6/#E3E6E8), jobs-list-page.tsx:36 and job-detail-page.tsx:251 'Short'/'Pick short' badge (#F7E9E4/#A13406), grid-columns.tsx:25 ShortPill, job-detail-page.tsx:209 pick-path done marker, job-types-page.tsx:57 usage pill (#D5E5F2/#0D36A3), and job-modals.tsx:52-54 priority card colors. All of them render as light islands on the dark theme.","report-pages.tsx:139 ReasonCell: replace `text-[#C8102E]` with a danger token that has a dark-mode value of at least #F87171. #C8102E on the dark navy surface is about 3:1, which fails WCAG AA for the 12-13px shortage-reason text.","wave-rules-page.tsx:69 NextRunCell: replace `text-[#B26A00]` with a warning token that has a dark-mode value; the amber under-2-minute countdown is too dim on dark.","src/lib/grid-defs/jobs/columns.ts WAVE_LOG_COLUMNS (around line 222): widen '# of orders met rule set criteria' to 250, '# of shortage orders' to 170, '# of jobs created' to 145, '# of allocated orders' to 175 and '# of merged orders created' to 215. Also give the header label span `truncate` (text-overflow: ellipsis) in the shared DataGrid header so long labels never draw into the next column. Today the headers collide, for example 'CRITERIA# OF SHORTAGE ORDERS'.","src/components/jobs/job-detail-page.tsx setTab (around line 314): keep the active tab in local state, update it immediately, and then router.replace the URL, or use window.history.replaceState. Switching tabs now waits for a full RSC round-trip, so under load clicking 'Tasks' changes nothing for seconds and the click feels dead.","src/lib/grid-defs/jobs/columns.ts: make the visible task-detail numeric/text columns sortable. Remove `sortable: false` from toPackType, uomPackType, targetCart, damageReason, taskUomQty, initialPackQty, initialApprovedPackQty and approvedPackQty, and add the matching server sort keys in the tasks repository.","src/lib/grid-defs/jobs/columns.ts:29: make 'Original job type' (Logiwa 'ORIGINAL IO JOB TYPE ?') visible by default with its tooltip, so Job Management shows all 32 columns as Logiwa does.","Wave run summary copy (server waves-run summary builder) and the task execute partial-pick callout (src/components/tasks/task-actions.tsx): use plural() so the text reads '1 job' and '1 unit short' instead of '1 jobs' and '1 units short'.","wave-rule-steps.tsx ScheduleStep: hide 'Not scheduled: the rule runs only when you press Run.' as soon as a day is selected, and keep the 'N daily frequency' pill on one line (`whitespace-nowrap`).","wave-rule-wizard.tsx Body / GeneralStep: delete the duplicate 'General' heading. The step title and the section title both read 'General'.","wave-rule-steps.tsx GeneralStep: when Next fails validation, give the job-type list container a red border. Logiwa reds Name, Warehouse and the job-type section; KitStaks only shows helper text.","wave-rule-wizard.tsx AiJobGate: add a footer with Back (to the operation-type cards) and Close. The AI job empty state is currently a dead end that can only be left with the drawer X.","Wave rules data and scheduler: 'B2B Wholesale Wave' and 'D2C Daily Waves' show Scheduled=Yes with no NEXT RUN, and their last run was days ago. Either recompute nextRunAt for scheduled rules (src/server/scheduler/tasks/wave-rules.ts) or show 'Not scheduled'. Also drop the out-of-domain priority 'Urgent' on 'Rush - Prime & Urgent'; the wizard only offers None/Low/Medium/High.","Wave rule Assign step (users grid) and the job Assign modal: filter out Client-type users and Viewer roles. Dana Whitfield and Marcus Oyelaran (client users) are offered as pickers, and seed job Job005263 is assigned to a client user.","Order Operations task grid: replace the literal 'No img' placeholder in the Product image column with a neutral image glyph, and normalize the order type value. 'D2C' and 'D2C Order' both appear in the same grid and on the Shortage report.","Wave rule Order By options (rule-editors.tsx): add Note, ExtraNote1, ExtraNote2, CustomFieldDateTime3, CustomFieldToggle2, CustomFieldDropDown2 and CustomFieldTextBox2-3, and add 'SO custom field toggle 2' to the Add Filter field list, to match the spec.","Brand-red overload (globals.css tokens): link cells (Job code, Order code, SKU, Wave rule name), active tabs, the primary CTA, selected segments and error text are all the same red. Move links to a neutral or blue link token so red is reserved for danger/shortage, as Logiwa uses indigo for links.","Job cancel and wave rule delete ConfirmDialogs (job-actions.tsx:199, wave-rules-page.tsx): change the 'No'/'Yes' buttons to explicit verbs ('Keep jobs' / 'Cancel 1 job', 'Keep rule' / 'Delete rule').","IA consistency: the jobs tab group sets the breadcrumb and top-nav highlight to Fulfillment on /jobs, Automation on /jobs/wave-rules and Reports on /jobs/shortage and /jobs/wave-log. Pin the whole tab group to Fulfillment > Jobs so the top nav does not jump while you move between tabs.","Seed data: purge the junk shortage rows with SKU '12341234' / product '12342134', and keep the KS-TEST-* noise out of the default demo dataset so the Shortage report reads as believable."],"functional_failures":["Dark mode, light-only schedule chip. Repro: in dark mode go to /jobs/wave-rules, click 'Create a new wave rule', choose Picking, fill Rule set name 'KS-TEST M03 Audit Rule', choose MLT1, check a job type, Next, Next. On Schedule, click 'Monday +'. The active chip renders as a pale mint pill (bg rgb(211,240,227), text rgb(23,135,77)), a light-only surface on the dark drawer. The cause is the hardcoded classes in wave-rule-steps.tsx:317.","Dark mode, light-only pills and low-contrast text. Repro: in dark mode open /jobs/shortage. The 'Shortage' order-status pill and the 'No' missing-triggered pills are light pastel pills on the dark grid. The shortage reason text 'Insufficient Inventory' is #C8102E on dark navy (about 3:1, fails AA). The Label status pill, the 'Short' badge and the job-type usage pill in jobs-list-page.tsx, grid-columns.tsx and job-types-page.tsx use the same hardcoded light hex colors.","Wave log headers collide. Repro: open /jobs/wave-log at 1440px wide. '# OF ORDERS MET RULE SET CRITERIA' (scrollWidth 237 in a 220px column) runs into '# OF SHORTAGE ORDERS', which itself overflows (159/150), and the same happens for '# of jobs created' (134/130), '# of allocated orders' (165/160) and '# of merged orders created' (203/190). The headers use text-overflow: clip with no ellipsis.","Job detail tabs feel dead. Repro: open /jobs/110ce49a-c589-4a45-9461-21909dc9eb88 (Job005279) and click the 'Tasks' tab. The tab gets focus but the Orders table stays on screen; the content only switches after the router.replace server round-trip finishes (more than 5 s observed while the dev server was under load). There is no local optimistic tab state.","Scheduled rules without a next run. Repro: open /jobs/wave-rules. 'B2B Wholesale Wave' and 'D2C Daily Waves' show Scheduled = Yes, but NEXT RUN is '—' and their last runs are 11/04 and 11/05 while today is 11/09. A scheduled rule never shows a countdown.","Grid sort race. Repro: on /jobs (default chip Job status Pending, Started), click column headers quickly one after another (about 1 s apart) and end on 'Pending tasks'. In one run the header showed aria-sort=ascending and the URL showed sort=pendingTasks, but the rows rendered as [5,1,4,1,0,1,2,2]. The network log showed earlier sort requests marked '200 OK [FAILED: net::ERR_ABORTED]', so a stale response appears to have won. The API itself sorts correctly.","Pluralization bugs. Repro 1: run a wave rule that creates one job (POST /api/wave-rules/run for 'KS-TEST M03 Audit Rule'); the toast reads 'Wave 108-1 completed: 20 met · 5 allocated · 1 jobs · 15 shortage'. Repro 2: on /tasks/order-operations select Picking task 1443, choose Task operations > Execute, then lower Quantity from 2 to 1; the callout reads 'Partial execute: 1 units short'.","Unsortable task columns. Repro: on /tasks/order-operations the visible columns 'To pack type', 'UOM pack type', 'Target cart', 'Damage reason' and 'Task UOM qty' have no sort control. On /tasks/count, 'Initial task pack qty', 'Initial task approved pack qty' and 'Approved pack qty' are unsortable (`sortable: false` in src/lib/grid-defs/jobs/columns.ts).","Inconsistent schedule copy. Repro: in the Create wave rule wizard on step 3 Schedule, select Monday. The footer still says 'Not scheduled: the rule runs only when you press Run.' while Monday is active, and the '0 daily frequency' pill wraps onto two lines.","Job-type validation not highlighted. Repro: in the Create wave rule wizard, choose Picking and click Next with every field empty. Rule set name and Warehouse turn red, but the 'Select job types' section gets no red border; the spec requires the job type section to be flagged too.","AI job dead end. Repro: on /jobs/wave-rules click 'Create a new wave rule' and choose 'AI job'. The 'AI Jobs is not active' empty state has no Back or Cancel footer; the only way out is the drawer X, and you cannot return to the operation-type cards.","Client users offered as assignees. Repro: in the Create wave rule wizard, step 4 Assign > 'Assign to users' lists Dana Whitfield (role Client) and Marcus Oyelaran (role Client) as assignable pickers. Seed job Job005263 on /jobs shows assignee Marcus Oyelaran, a client user."],"logiwa_wins":["Per spec, Logiwa's Job Management shows all 32 columns by default, including 'ORIGINAL IO JOB TYPE ?' with its tooltip. KitStaks hides Original job type by default and shows 31.","Per spec, Logiwa uses indigo for link cells and keeps red for semantic danger and the High priority pill. KitStaks uses the same red for links (Job code, Order code, SKU, Wave rule name), the CTA, active tabs, selected segments and error text, so status color loses its meaning.","Per spec, Logiwa's wave rule Order By list includes Note, ExtraNote1, ExtraNote2, CustomFieldDateTime3, Toggle2, DropDown2 and TextBox2-3, and its filter list includes SO Custom Field Toggle 2. KitStaks offers 11 order-by options and leaves out Toggle 2.","Per spec, Logiwa flags the job-type section with a red border when Next is pressed with nothing selected on General. KitStaks only shows helper text under the list.","Per spec, Logiwa's status and pill colors are a coherent computed set. KitStaks hardcodes light-theme hex pills (Label status, Short, schedule day chips, job-type usage, shortage reason red) that break in dark mode.","Per spec, Logiwa's wave log columns read cleanly. KitStaks' wave log headers overflow into each other without ellipsis.","Per spec, Logiwa keeps the whole Jobs section under one breadcrumb (Home > Orders > Jobs > ...). KitStaks moves the breadcrumb and top-nav highlight between Fulfillment, Automation and Reports as you switch tabs inside the same tab group.","Per spec, Logiwa's Task Details headers are sortable where shown. KitStaks leaves several visible qty and pack-type columns unsortable on Order Operations and Count."]},"M04":{"scores":{"hierarchy":7,"density":7,"color":6,"craft":6,"states":6,"sideBySide":7,"functionality":7,"completeness":7},"verdict":"not_wowed","blindPick":"A","blindMapping":"spec-based audit, no live blind comparison","kitstaksWins":false,"fixes":["src/components/grid/data-grid.tsx (header cell) + src/components/returns/return-columns.tsx: header labels overflow their fixed widths and collide (FROM COUNTRY NAME 161px of content in a 130px column renders as 'FROM COUNTRY NAMSTATUS'; also SHIPMENT ORDER CODE 168>150, REQUESTED QUANTITY 163>120, RETURNED QUANTITY 156>120, CARRIER SHIPPING OPTION NAME 224>200, RETURN ORDER CREATED DATE 209>172, SHIPMENT ORDER DELIVERY DATE 226>172). Add `min-w-0 overflow-hidden` + `truncate` with a title tooltip on the header label span, or widen these columns in return-columns.tsx to at least the measured label width + 24px.","src/components/packing/pack-screen.tsx (product scan error state): clear the scan error ('X is already fully packed... Over-packing is blocked.') on the next successful scan, on Close pack (F2), and when the package state changes; today it stays under the input after the package is Closed.","src/components/returns/return-receive-flow.tsx: clear the line scan error ('X is not on this return.') and the 'Not received / Scan at least one item' banner as soon as a valid scan raises any line above 0; both stay visible after a successful NOVA-HUB-7P scan.","src/components/returns/return-orders-page.tsx StatusPills: the 'All 20' pill counts RMAs while the grid footer says 'Total: 25' (lines). Either have /api/returns/summary count lines, or label the pills 'RMAs' and the footer 'lines' so the numbers reconcile.","src/app/api/packing/kpis (Total orders to be packed) vs src/app/api/packing/orders (List & select): the dashboard KPI says 2 while the List & select modal for the same warehouse lists 1 order. Use the same predicate (Ready to Pack + Packing Started with complete picks) in both, or make the KPI link land on exactly the orders the modal shows.","src/app/api/packing/scan: scanning an order that is already packed (Ready to Ship) returns 'No allocated order found. Please transfer the products to another location.' Return a specific 409 message such as 'KS-E2E-SO-2 is already packed (Ready to Ship).' and echo the scanned code in the error under the input.","src/components/returns/rma-create-page.tsx Items step: disable the Return qty input until its row checkbox is checked, or auto-check the row when the qty is edited. When a typed qty exceeds the cap (typed 9, shipped 2), show an inline 'Max 2 (shipped minus already returned)' instead of silently clamping.","src/components/returns/rma-create-page.tsx progress rail: the ring jumps 33% to 67% on step 1 once an order is picked, and drops from 100% back to 67% when 'Create return label' is toggled on. Drive it from completed steps only. Also make the step-2 completed check the same green token as step 1 (it renders lime).","src/components/returns/rma-detail-page.tsx header: render 'RMA000331' rather than 'RMA RMA000331', and drop the redundant grey 'RMA' badge, or rename the badge to the source (RMA / Manual).","Timeline writer for return_order status (src/server/repositories/returns*.ts): log the Pending → Started transition when receiving begins. The timeline now shows 'Status is modified. Started --> Completed' with no Started event. Also replace the ASCII ' --> ' format and Title Case field names with sentence-case copy such as 'Status changed from Started to Completed'.","src/server/repositories/returns*.ts complete: set the return label status to Used/Consumed (not 'Active') once the RMA is Completed.","src/components/returns/rma-detail-page.tsx Cancel confirm: change the 'No' / 'Yes' buttons to 'Keep RMA' / 'Cancel RMA' (danger variant), and state whether the active return label will be voided.","src/components/returns/return-station-page.tsx: when opened with ?rma=, look up the RMA's warehouse and preselect it, plus that warehouse's remembered station. Today 'Receive at station' lands on an empty 'Choose a warehouse' and the user must re-pick MLT1.","src/components/packing/list-select-modal.tsx: replace the native <input type=date> ('mm/dd/yyyy' with the browser calendar icon) with the design-system DatePicker. In rma-create-page.tsx, change the Expected return date placeholder from 'YYYY/MM/DD' to the app-wide MM/DD/YYYY. Standardize the RMA detail and Create RMA dates ('11/4/2026 3:15:00 PM') on the grid format 'MM/DD/YYYY h:mm AM'.","src/components/packing/pack-screen.tsx job card: in Order mode the copy reads '# of orders in order: 0/1 packed'. Use a mode-aware label: 'Orders in tote' / 'Orders at location' / hide it in Order mode.","Pack and return item cards (pack-screen.tsx, return-items.tsx): the image fallback renders raw initials 'NO' / 'VL'. Use the product image, or a neutral package glyph.","src/components/returns/return-receive-flow.tsx (manual): pluralize '1 units' → '1 unit'. Give the two scan inputs distinct accessible names ('RMA, order or tracking scan' / 'Item scan'); both are currently 'Scan or type, then press Enter'. Associate the Create RMA 'Note' label with its textarea via htmlFor/id.","src/lib/nav (top nav) + PageHeader breadcrumbs for /orders/returns and /return-station: the breadcrumb says Home > Inventory > Return Orders and the Inventory nav lights up, yet the page shows the Orders tab strip (ORDER BACKLOG / SHIPPED & CANCELED / RETURN ORDERS). Put Return Orders under Orders (Home > Orders > Return Orders) as Logiwa does.","src/components/returns/return-columns.tsx: make Return Address and Tags sortable, or add returnAddress/tagNames to RETURN_SORT_FIELDS (they are currently the only unsortable data columns).","Grid refetch state (src/components/grid/data-grid.tsx): after a status pill or sort click, the stale rows stay fully opaque for 5–10 s under the new filter (Pending pill active while Completed/Cancelled rows still show). Show a top progress bar and dim the stale rows while isFetching.","Dark-mode disabled CTAs (return-station-page.tsx BigAction and the pack footer 'Complete packing and create label'): opacity-55 on a dark surface leaves the title and description nearly unreadable. Use a dedicated disabled token (text-faint on surface-sunken) that keeps 4.5:1 contrast for the label text.","Brand primary is red, so focus rings and selected states (Change status note textarea on open, Create RMA Cancel button border, scan inputs) read as error states. Switch the focus ring to a neutral or blue focus token and reserve red for danger and validation."],"functional_failures":["Return Orders grid header collision: open /orders/returns at 1440px wide → the header row shows 'FROM COUNTRY NAMSTATUS'. The FROM COUNTRY NAME label (161px) overflows its 130px column into STATUS. REQUESTED QUANTITY (163/120), RETURNED QUANTITY (156/120), CARRIER SHIPPING OPTION NAME (224/200), RETURN ORDER CREATED DATE (209/172) and SHIPMENT ORDER DELIVERY DATE (226/172) overflow the same way.","Stale over-pack error on the pack screen: /packing-station → MLT1 / PACK-01 → List and select order → KS-E2E-SO-2 → Start packing → scan NOVA-HUB-7P + serial → scan NOVA-HUB-7P again ('already fully packed... Over-packing is blocked.') → pick BOX-S, set weight, F2 to close the package → the over-pack error is still shown under the product scan input.","Stale errors at the Return Station: /return-station?rma=RMA000331 → MLT1 / MLT1-RTN → press Complete return with 0 units ('Not received / Scan at least one item') → scan KS-TEST-NOT-ON-RMA (error shown) → scan NOVA-HUB-7P (1/1 units) → both 'KS-TEST-NOT-ON-RMA is not on this return.' and the 'Not received' banner stay on screen.","Packing KPI mismatch: /packing-station → MLT1 → PACK-01 → right card 'TOTAL ORDERS TO BE PACKED 2' → List and select order → the modal lists only 1 order ('1 order', KS-E2E-SO-2).","Misleading error for an already-packed order: after packing KS-E2E-SO-2 (Ready to Ship), scan KS-E2E-SO-2 in the Order scan input → GET /api/packing/scan returns 409 and the UI says 'No allocated order found. Please transfer the products to another location.' It should say the order is already packed.","Return Orders count mismatch: /orders/returns → the 'All' pill reads 20 while the grid footer reads 'Total: 25' for the same unfiltered view, with no labelling that one counts RMAs and the other lines.","Create RMA quantity behaviour: /orders/returns/new → choose SO010836 → Next → type 5 into NOVA-CBL-LTG-2M Return qty without ticking its row → the field shows 1 and the summary stays '0 units selected'. With a row ticked, typing 9 is silently clamped to 2 with no message.","RMA timeline is missing a transition: create RMA000331 (Pending) → receive it at /return-station → the RMA detail timeline shows 'Status is modified. Started --> Completed', with no Pending→Started event. The return label still shows LABEL STATUS 'Active' after completion.","'Receive at station' deep link does not preselect the warehouse: on /orders/returns/{id} for an MLT1 RMA, open /return-station?rma=RMA000331 → Receiving warehouse is 'Choose a warehouse' and both start buttons are disabled until MLT1 and the station are picked again by hand.","Native browser date control: /packing-station/{station}/order?list=1 → the List and select modal's 'Expected ship date' filter is a native <input type=date> (mm/dd/yyyy plus the browser calendar icon). The Create RMA Expected return date uses YYYY/MM/DD, unlike the app's MM/DD/YYYY.","Copy and grammar defects: Return manually → scan one VLT-SPK-MINI → the counter reads '1 units'. The pack screen job card in Order mode reads '# of orders in order: 0/1 packed'. The RMA detail title reads 'RMA RMA000331'. The Cancel RMA confirm uses generic 'No' / 'Yes' buttons.","No loading state on refetch: on /orders/returns click the 'Pending' pill → for 6–10 s the grid shows unfiltered rows (Completed, Cancelled, In Transit) at full opacity under the active Pending filter, with no busy indicator.","Accessibility: on the Return Station RMA flow both scan inputs share the accessible name 'Scan or type, then press Enter'. The Create RMA Note textarea is named only by its placeholder. The packing dashboard mode buttons are exposed as unnamed 'button' elements inside 'Choose a warehouse first' wrappers."],"logiwa_wins":["Per spec, Logiwa's package contents grid shows Image, Product, Pack Type, Label, Weight, Quantity and Attributes, with a Total SKU / Total Quantity footer. KitStaks shows only Product, Label and Qty.","Per spec, Logiwa keeps the right-pane controls (Package Type, L/W/H, weight, Carrier/Service, Get Rate, Label) visible but disabled until an order loads, so packers learn one fixed layout. KitStaks shows a large empty panel ('Scan order to start') with no controls.","Per spec, Logiwa files Return Orders under Orders (Shipment Order > Return list, Orders breadcrumb). KitStaks' breadcrumb and top nav put it under Inventory while showing the Orders tab strip, which is inconsistent.","Per spec, Logiwa's Return Orders toolbar pairs Export as Excel with Excel Export History. In KitStaks, Export As Excel only POSTs /api/exports (202) and showed no confirmation or history entry point on the page.","Per spec, Logiwa's 25 return columns read cleanly. KitStaks' fixed-width headers overflow and overlap ('FROM COUNTRY NAMSTATUS'), and Return Address and Tags cannot be sorted."]},"M05":{"scores":{"hierarchy":7,"density":7,"color":7,"craft":6,"states":5,"sideBySide":6,"functionality":5,"completeness":7},"verdict":"not_wowed","blindPick":"A","blindMapping":"spec-based audit, no live blind comparison","kitstaksWins":false,"fixes":["src/server/domain/ledger/receipts.ts (cancel path near line 154) + purchase-orders repository: when a receipt is reversed, recompute PO status from the remaining active receipts. Started with 0 received goes back to Pending, and receivedAt is cleared when no active receipts remain. Write a change-log entry for each field reverted.","src/server/domain/ledger/receipts.ts line 68: stop stamping `receivedAt: po.receivedAt ?? nowIso()` on the first receipt. Stamp Actual Receiving Date (and CompletedDateTime) only when the transition goes to Completed, as the spec says.","src/components/receiving/receipt-drawer.tsx: after onCancel succeeds, invalidate or refetch the receipt-detail query (or close the drawer). This makes the drawer show the Cancelled callout and disables Cancel receipt, so the user cannot fire a second cancel that returns 409.","Change-log formatter (shared ChangeLogDrawer / PO audit writer): format date fields with fmt.dateTime instead of writing raw ISO strings. The current entry reads 'Actual Receiving Date is modified. --> 2026-11-09T22:20:39.489Z'. Also log line creation as '<SKU> -> Purchase order line is created.' instead of 'Ordered Qty is modified. --> 10'.","src/components/shared/address-card.tsx line 34: render the address whenever any of line1/city/state/postalCode/country is present. Do not require line1. A vendor with City=Mobile, State=AL currently shows 'No address on file' on the PO Confirm step while the Vendors grid shows 'Mobile, Alabama'.","src/components/receiving/wizard/step-products.tsx: the 17-column lines table makes the whole document 1846px wide at a 1440px viewport, so the app shell scrolls horizontally. Wrap the table in a container with `min-w-0 overflow-x-auto`, and add `min-w-0` to the wizard's flex/grid column parents so the overflow stays inside the card.","src/components/receiving/wizard/po-wizard.tsx (stepper): after jumping to step 1 on an existing PO and saving, the stepper still highlights Step 1 as current while the body shows Confirm. Derive the current-step highlight from the same state that drives the body. Also give visited-optional and just-completed steps one consistent treatment: no brown fill, no red-filled check.","src/components/receiving/wizard/po-wizard.tsx (PO Status ring): drive the % from completed steps (0/25/50/75/100) and disable Confirm purchase order until step 5, per spec. Today the ring shows 25% on an empty form and 100% 'Ready to save' at step 3. On an unchanged existing PO, show 'Saved' rather than 'Ready to save'.","src/components/receiving/wizard/step-products.tsx: disable Next (with a DisabledReason tooltip) while lines.length === 0, instead of allowing the click and then showing 'Add at least one product'.","src/components/receiving/wizard/po-product-search.tsx ResultRow: show a spinner on the + button and disable it while fetchProductInfo runs. The Edit Product drawer took 10+ s to open with no feedback. Also flip the button to the 'On this order' state for every added SKU (the second added SKU kept the red primary +).","src/components/receiving/receive-items-drawer.tsx: replace the raw putaway reason dump ('Check Damaged Locations · Suggest a location with the selected area type · Suggest an empty location (SAME_SKU_EMPTY_LOCATION_ALGORITHM · Empty storage location)') with one human sentence, e.g. 'Empty storage location in zone A'. Never render enum codes. Do not mention damaged-location rules on an undamaged receipt.","src/components/receiving/receive-items-drawer.tsx: validate every selected line and show all missing tracked attributes at once (lot and expiry together), not one error per Receive click. Give the quantity NumberInput an aria-label like 'Quantity to receive for <SKU>'; its accessible name is currently '0'.","src/components/receiving/receive-items-drawer.tsx: pin the '1 line · 6 units selected' summary into the sticky footer next to Cancel/Receive. It currently floats in the middle of the drawer body. Stop drawing a red border on selected line cards, because a red border reads as an error state; use the neutral selected border token.","src/components/receiving/po-columns.tsx: widen PO Number to fit 18–20 characters (≈170px) or let it auto-size. 'KS-TEST-E2E-4…', 'KS-TEST-DETAIL…' and 'KS-TEST-PO-M…' are truncated even though the grid has spare width. Apply the same change to PO Number in src/components/receiving/receipt-columns.tsx.","src/components/receiving/po-list-page.tsx: before opening the Receive PO confirm, check the selected POs for lot/expiry/serial-tracked open lines. Disable the action with a reason, or list the blocked POs inside the confirm. Today it confirms, then fails with '0 of 1 orders received · 1 failed'.","src/components/receiving/po-list-page.tsx: remove the permanently disabled 'Remove serial number' item (SERIAL_PREADVICE_REASON placeholder) or implement it. Dead menu items are not acceptable.","Breadcrumbs and titles: use one hierarchy for the module. The list is 'Home > Inventory > Purchase Orders', Vendors is 'Home > Inventory > Purchase Orders > Vendors', History is 'Home > Inventory > Receiving History', and the wizard is '… > New Purchase Order' under an H1 'Create purchase order'. Use sentence case everywhere ('Purchase orders', 'New purchase order'). Fix the Title Case copy 'Custom Fields' and 'Create Custom Field' on step 4 (src/components/receiving/wizard/po-wizard.tsx / custom-field section).","src/components/receiving/po-create-page.tsx success state: hide the 'Cancel order' header button once the PO is created, and lay the 3 next-step cards out in one row of 3 (grid-cols-3) instead of 2+1.","Date formatting: use one formatter across the module. The list shows '11/06/2026 9:00 AM', the detail '11/9/2026', History expiry '5/8/2027' and the receipt drawer '11/9/2026 4:20:39 PM'. Pick the useFormat().date/dateTime pattern everywhere.","Warehouse label on Confirm/Order Details: show 'MLT1 - Main Fulfillment', not 'MLT1 · MLT1 - Main Fulfillment'. Drop the duplicated code prefix in step-confirm.tsx.","src/components/receiving/po-list-page.tsx header: render Import/Create purchase order placeholders (or reserve their space) while permissions load. They currently pop in after the grid loads and shift the toolbar.","Detail-page loading skeleton (shell-skeleton / po-detail-page.tsx): match the real layout's 24px page gutter and the stepper/rail geometry. The current skeleton is edge-to-edge and jumps on load.","Receiving history grid: hide the 'Selected: 0' footer counter on grids with no selection column (receiving-history-page.tsx / DataGrid footer prop). In the PO wizard vendor step, keep the footer 'Selected' in sync with the radio selection (it showed 0 while a vendor was selected)."],"functional_failures":["Cancelling a receipt leaves the PO in a wrong state. Steps: 1) Create PO KS-TEST-PO-M05R1 (2 lines, 10 + 5). 2) On /receiving/<id> click Receive items and receive 6 of line 1 (lot L123, expiry 2027/05/08); the PO becomes Started. 3) Go to /receiving/history?q=KS-TEST-PO-M05R1, click Master Id 70125, click Cancel receipt, then Yes. 4) GET /api/purchase-orders?q=KS-TEST-PO-M05R1 returns status 'Started', receivedQuantity 0, activeReceipts 0, receivedAt '2026-11-09T22:20:39Z', and the list and detail still show Started. Expected: the PO reverts to Pending and Actual Receiving Date is cleared.","Actual Receiving Date is stamped on a partial receive. Steps: receive 6 of 15 units on a Pending PO through Receive items, then open Show change log. The log shows 'Actual Receiving Date is modified. --> 2026-11-09T22:20:39.489Z' while the PO is only Started. The spec says Completed stamps Actual Receiving. The value is also a raw ISO string.","The receipt drawer is stale after cancel and allows a duplicate cancel that gets a 409. Steps: on /receiving/history open the Master Id drawer for an active receipt, click Cancel receipt, then Yes (POST /api/receipts/<id>/cancel returns 200). The grid row now shows 'Cancelled', but the drawer still shows PO status Started and an enabled Cancel receipt button. Clicking it again and confirming sends POST /api/receipts/<id>/cancel, which returns 409 Conflict.","The vendor address is dropped on the PO Confirm step. Steps: in the /receiving/new step 3, click Add new vendor and enter Display name, Vendor name and City=Mobile (Country US, State Alabama defaults). Save and continue to step 5. The Vendor card shows 'No address on file' for Shipping and Billing, while /receiving/vendors shows Ships from 'Mobile, Alabama'.","Page-level horizontal scroll in the wizard. Steps: at a 1440x900 viewport on /receiving/new, complete step 1 and add 2 products on step 2. document.documentElement.scrollWidth becomes 1846 (window.scrollX reached 330), so the whole top nav and page scroll sideways. The lines table (width 1862px) is not contained.","The stepper is out of sync on the PO detail. Steps: open /receiving/<id>, click 'Step 1: PO details', edit Note, then click Save purchase order. The body returns to the Confirm view, but the stepper still highlights STEP 1 as current with the red box.","Next on wizard step 2 is not disabled when there are no lines. Steps: on /receiving/new complete step 1 and land on Products with zero lines. Next is enabled, and clicking it shows the 'Add at least one product' error. The spec says Next stays disabled.","The PO Status ring and Confirm do not follow the spec. Steps: open /receiving/new; the ring reads 25% before any input. After the vendor is selected on step 3 it reads 100% 'Ready to save', and Confirm purchase order is enabled at step 3. The spec says the ring goes %0→%100 by step and Confirm is enabled only at step 5.","Bulk Receive PO confirms and then fails on tracked products. Steps: on /receiving select a PO whose lines are lot/expiry tracked (KS-TEST-PO-M05R1), click Receive PO, then click Receive. The error toast reads '0 of 1 orders received · 1 failed. …CPL-BAG-DEC-12 is lot tracked…'. The action should be gated before the confirm.","A dead menu item. Steps: on /receiving select any row and open Delete ▾. 'Remove serial number' is permanently disabled with 'Serial number pre-advice isn't set up for purchase orders yet.', which is a placeholder.","The putaway suggestion leaks internal enum and rule text. Steps: open Receive items on a PO in MLT1. Under Receiving location the suggestion reads 'Suggested KST-A-01-1 — Check Damaged Locations · Suggest a location with the selected area type · Suggest an empty location (SAME_SKU_EMPTY_LOCATION_ALGORITHM · Empty storage location)'.","Add-product gives no feedback. Steps: on wizard step 2 search 'CPL' and click + on a result. Nothing visibly happens for about 10 seconds (no spinner, button not disabled) before the Add product drawer opens. A user can double-click and queue duplicate fetches.","The PO Number column truncates the primary identifier. Steps: on /receiving search 'KS-TEST'. The PO Number column shows 'KS-TEST-E2E-4…', 'KS-TEST-DETAIL…' and 'KS-TEST-LIST-1…' at 1440px with spare width. Receiving History also truncates 'KS-TEST-PO-M…'.","Tracked-attribute validation shows one error per attempt. Steps: in Receive items select a lot+expiry tracked line with both fields empty and click Receive. Only the 'lot tracked' error shows. After entering the lot, clicking Receive again only then reveals the 'expiry tracked' error."],"logiwa_wins":["Per spec, Logiwa's Cancel Order works on Started POs (Pending/Started). KitStaks disables Cancel order on a Started PO that has receipts ('Cancel its receipts first'), which forces a receipt-by-receipt reversal first.","Per spec, Logiwa's bulk Receive PO is a one-click full receive that works for every PO. KitStaks's bulk Receive PO fails for lot/expiry/serial-tracked POs and only reports the failure after the confirm.","Per spec, Logiwa's PO Status ring progresses step by step (%0→%25→%50→%75→%100), and Confirm is enabled only at step 5. KitStaks starts at 25% and reports 100% 'Ready to save' at step 3, so the progress signal is meaningless.","Per spec, Logiwa's Change Log shows human field names, formatted dates and an explicit 'Purchase Order Line is created' entry. KitStaks logs raw ISO timestamps and records line creation as 'Ordered Qty is modified. --> 10'.","Per spec, Logiwa's Step 2 Next is disabled until a line exists. KitStaks leaves Next enabled and errors after the click.","Per spec, Logiwa's right rail has Save Purchase Order at the top and repeated at the bottom. KitStaks shows it only at the bottom of an overloaded rail that repeats the same PO number, vendor and total in two cards.","Per spec, Logiwa's vendor drawer has an 'Address name' field. KitStaks has 'Contact name' instead, and its Confirm vendor card hides partial addresses that Logiwa's Shipping/Billing cards would show.","Per spec, Logiwa's Receiving History grid has no selection footer clutter. KitStaks shows a meaningless 'Selected: 0' on a grid with no row checkboxes."]},"M06":{"scores":{"hierarchy":8,"density":7,"color":7,"craft":7,"states":6,"sideBySide":8,"functionality":7,"completeness":8},"verdict":"not_wowed","blindPick":"A","blindMapping":"spec-based audit, no live blind comparison","kitstaksWins":false,"fixes":["src/components/inventory/quantity-drawer.tsx and add-inventory-drawer.tsx (and change-attributes-drawer.tsx): Save is enabled on a pristine or invalid form and the code validates only on submit (add-inventory-drawer.tsx line 96 comment). Derive canSave = form valid && dirty, pass disabled={!canSave} to the Save Button, and show the field errors on blur. The quantity-drawer.tsx header comment already promises 'Save stays disabled until the form is valid'; make the code do that.","change-attributes-drawer.tsx: Save is enabled while Damage Reason is still the default 'No damage reason' on a row that has no damage reason, so it saves a no-op. Disable Save until the selected value differs from the current value of every selected row.","Warehouse option labels in add-inventory-drawer.tsx (WarehouseSelect / combobox-data option builder): options render 'MLT1 · MLT1 - Main Fulfillment' and the selected value renders 'MLT1 - MLT1 - Main Fulfillment'. The warehouse name already contains its code, so render just the name (or code + bare name). Apply the same fix in transfer-container-drawer.tsx.","add-inventory-drawer.tsx Pack Type: when the product has exactly one pack type (e.g. HRB-FLTR-100 has only 'Unit'), preselect it rather than making the user open a one-item dropdown.","add-inventory-drawer.tsx Product combobox: options list only the SKU (HRB-BAG-CLD-12 ...). Render SKU on the first line and product name on a muted second line, as Logiwa shows 'MLT-WIDGET-01 - MLTest Widget'.","bucket-drawer.tsx: after a row click the drawer opens with only the title 'Inventory' and an empty body until /api/inventory/buckets/:id resolves (>10s seen). Render a skeleton (summary card, tab strip, field grid) while loading, and an error state with Retry on failure.","DataGrid refetch (src/components/grid/data-grid.tsx): after applying the Warehouse filter on /inventory, the old 'All Warehouses' rows stay up with no indicator for about 5s. Show a 2px top progress bar or dim the tbody (opacity 0.6) while isFetching && !isLoading.","Date formatting: the grid shows '08/23/2026 8:00 AM' while the bucket drawer shows '8/23/2026 8:00:00 AM'. Route both through the shared formatDateTime helper (zero-padded, no seconds).","bucket-card.tsx: the label 'TRANSFER FROM' is reused in the read-only bucket detail header and in the Adjust/Damage drawers. Use 'LOCATION' everywhere except the Transfer Product drawer.","Color semantics (inventory-links.ts / link cell style): SKU hyperlinks render in brand red, the same red as negative quantities ('-2' in Available UOM Qty) and the danger chips, so links read as errors in dark mode. Use a neutral link token (e.g. --link: #7FA7FF dark / #1D4ED8 light) with an underline on hover, and keep red for negatives and errors only.","Walking Path Priority (by-location-columns.tsx): rendered with thousands separators ('2,040', '1,230'). It is an ordinal sequence, not a quantity, so render it as a plain integer with no grouping.","Open SO Qty hyperlink (inventory-links.ts): the href is a raw '/api/inventory/open-orders?productId=<uuid>' redirect, so the status bar and copy-link expose an API URL and a UUID. Link directly to '/orders?f.sku=eq:<sku>&f.warehouse=in:<id>&f.status=in:open…' as the build plan specifies, or to a pretty /inventory/open-orders route.","Search comparator (grid-toolbar.tsx): defaults to 'Starts With'. The spec default is 'Equal'. Default to Equal, or persist the user's last choice per grid.","Enum filter editor (grid filter popover): the Warehouse/Client/Status checklists have no 'in | not in' operator and no search box. Add the operator dropdown and a search input above the checklist, per spec 04 §0.","quantity-drawer.tsx Remove mode and transfer-container-drawer.tsx Transfer Location (moves an entire location): add a ConfirmDialog summarising what will move or be removed ('Move 3 SKUs / 640 units from C-01-01-3 to …?') before posting to the ledger.","Seed data hygiene: ATP and the inventory grids show test junk in the demo tenant ('KS-TEST-KIT-34903 KS test UI kit', 'KS-E2E-PROD-1 KS E2E product one v2', clients 'KS-E2E Client' and 'KS-TEST Wizard Brand'), and every seeded receiving time is exactly 8:00 AM. Purge the KS-TEST/KS-E2E records from the demo dataset (or hide them behind a test-tenant flag) and jitter the seed timestamps.","Product Type column shows category values ('Tops', 'Packaging', 'Cables', 'Outerwear'). Logiwa Product Type is a type (Standard/Kit/Packaging Material). Map the column to the real product type and leave category to Product Group.","by-location-columns.tsx: Original LP Number, Parent LP Type and Original Parent LP are hidden by default, while Logiwa shows all 37 data columns. Make them visible by default (or document the deviation)."],"functional_failures":["Save is not disabled until the form is valid (violates spec 04 §0 and BUILD_PLAN M06 checklist 'Save is disabled until the form is valid'). Repro: /inventory/by-location, open the ⋯ on any Stock row (e.g. APX-TEE-BLK-L @ A-01-02-1), choose Adjust. With Adjustment Reason and New Quantity both empty, Save is enabled (button.disabled=false). Clicking it only then shows 'Enter a quantity'. The same happens in the header Add Inventory drawer (all fields empty, Save enabled).","Change Damage Reason allows a no-op save. Repro: /inventory/by-location?q=HRB-FLTR-100, check an undamaged row, Change Attributes ▾ > Change Damage Reason. The dropdown defaults to 'No damage reason', which equals the row's current value, yet Save is enabled.","Warehouse label shows the code twice. Repro: /inventory/by-location > Add Inventory > open the Warehouse dropdown. The options read 'KS2 · KS2 - Overflow' and 'MLT1 · MLT1 - Main Fulfillment'. After selecting, the field shows 'MLT1 - MLT1 - Main Fulfillment'.","The bucket drawer shows an empty body while loading. Repro: /inventory/by-location, click any row body cell. The drawer opens with only the heading 'Inventory' and a blank panel (no skeleton, no spinner) until GET /api/inventory/buckets/:id returns (over 10s observed).","Stale grid with no fetching indicator. Repro: /inventory, type APX-TEE in search and press Enter, then Filter > Warehouse > check 'MLT1 - Main Fulfillment' > Apply. The chip appears and the URL updates to f.warehouse=in:<id>, but for about 5s the grid still lists 'All Warehouses' rows with the old quantities and shows no loading cue.","Grid body collapses on a short viewport. Repro: open /inventory/by-location?q=HRB-FLTR-100 in a 740x403 viewport. Header, toolbar and footer render, but the table area has zero visible rows (not even the header row) while 'Total: 6' shows.","Very slow round-trips in this run, possibly caused by a heavily loaded shared dev server (node at 4.3GB RSS, Fast Refresh churn). Observed: GET /api/inventory/by-location took 21.9s on first load, product-options 38s, the Adjust Save POST about 12s, Add Inventory Save about 20s, and a reload of /inventory/by-location?q=HRB-FLTR-100 stayed on skeletons for more than 2 minutes before a later reload loaded. Not conclusive as an app defect, but there is no timeout or error state; the skeleton spins indefinitely.","Not verified because of the server degradation: the Only-1-SKU rule-guard message, the Transfer LP/Transfer Location Find→summary→Transfer happy path, and the per-column sort correctness on /inventory/by-location. A transfer of HRB-FLTR-100 into A-01-02-1 (which holds APX-TEE-BLK-L) succeeded, so that location has no 1-SKU rule; the guard is still untested in the UI."],"logiwa_wins":["Per spec 04 §0: Logiwa drawers keep Save disabled until the form is valid. KitStaks enables Save on empty forms and validates on submit.","Per spec 04 §0: Logiwa enum filters offer an 'in | not in' operator and a search box in the checklist. KitStaks enum filters (Warehouse, Client, Status) offer only a bare checklist.","Per spec 04 §0: Logiwa's search comparator defaults to Equal. KitStaks defaults to Starts With.","Per spec 04 §2: Logiwa shows all 37 Inventory by Location data columns by default. KitStaks hides Original LP Number, Parent LP Type and Original Parent LP by default.","Per spec 04 §2/§2.8: Logiwa's damage/hold reasons include OnHold and Quarantined (holds), plus Leaking, Extra and Bad Packaging. KitStaks' damage list (Damaged in Transit, Crushed Packaging, Water Damage, Expired, Manufacturer Defect, Broken Seal, Warehouse Handling Damage, Customer Return - Damaged, Damaged) has no hold or quarantine status.","Per spec 04 §2.4: Logiwa shows the product as 'SKU - Name' in the product picker. KitStaks lists bare SKUs only, which makes similar SKUs hard to tell apart."]}}


function specCriticPrompt(m, round) {
  return `You are a brutally harsh enterprise WMS buyer and UX critic auditing module ${m.code} "${m.id}" of KitStaks (http://localhost:3000, local test login admin@kitstak.io / KitStak!demo2026). Audit round ${round}.
The live Logiwa sandbox is NOT available this run. Use the captured Logiwa reference instead: references/logiwa-spec/*.md (field lists, wizard steps, menus, statuses, screenshots notes) plus the research JSON ${RESEARCH} (result.modules id "${m.id}": routes, checklist, acceptance, logiwaUrls) and docs/BUILD_PLAN.md module section starting line ${m.line}. Apply docs/CRITIC_RUBRIC.md. Do NOT open my.logiwa.com. Do NOT edit any code files.
Browser: built-in browser tools only; create your OWN tab with tabs_create, pass its tabId on every call, and CLOSE it before you finish (tab slots are limited). Prefer read_page/get_page_text; screenshots only when judging visuals.
Method: physically operate every route, grid (sort every column, filter, search, paginate, column chooser, export), pill, menu, kebab, bulk action, wizard (validation, back/next, cancel, finish), detail tab and inline edit this module owns. Create/edit records with "KS-TEST" prefixes and confirm they persist after reload; check read_console_messages and read_network_requests for errors/4xx/5xx. Also check dark mode (user menu > Appearance > Dark) on the module's main screens for unreadable text or light-only surfaces.
Compare against the Logiwa spec: anything Logiwa has that KitStaks lacks or does worse goes in logiwa_wins (say "per spec"). Set blindPick "A" and blindMapping "spec-based audit, no live blind comparison"; set kitstaksWins true only if KitStaks clearly beats the spec'd Logiwa screens.
Be harsh: dead buttons, placeholders, raw UUIDs, missing ConfirmDialog on destructive actions, unsortable columns, missing loading/empty/error states, Title Case copy, broken back-navigation, console errors, dark-mode contrast failures are all failures. Each functional_failures entry needs exact repro steps; each fixes entry names file/component and the concrete change.
verdict "wowed" ONLY if every score >= 9, zero functional_failures and zero logiwa_wins.`
}

function passesSpec(c) {
  if (!c) return false
  const s = c.scores || {}
  const allHigh = ['hierarchy', 'density', 'color', 'craft', 'states', 'sideBySide', 'functionality', 'completeness'].every(k => (s[k] || 0) >= 9)
  return c.verdict === 'wowed' && allHigh && (c.functional_failures || []).length === 0 && (c.logiwa_wins || []).length === 0
}

async function auditModule(m) {
  let last = null
  for (let round = 1; round <= ROUNDS; round++) {
    const critique = (round === 1 && SEED[m.code]) ? SEED[m.code] : await throttled(specCriticPrompt(m, round), { label: `${m.code}-audit-r${round}`, phase: 'Audit', schema: CRITIC_SCHEMA })
    if (!critique) { log(`${m.code}: critic errored in round ${round}; stopping this module`); return { id: m.id, code: m.code, wowed: false, rounds: round, critique: last, error: 'critic failed' } }
    last = critique
    if (passesSpec(critique)) { log(`${m.code}: WOWED in audit round ${round}`); return { id: m.id, code: m.code, wowed: true, rounds: round, critique } }
    log(`${m.code} audit r${round}: ${JSON.stringify(critique.scores)}; ${(critique.functional_failures || []).length} failures, ${(critique.logiwa_wins || []).length} spec gaps`)
    const prompt = builderPrompt(m, round + 1, critique) + `\nResume from docs/progress/${m.id}.md. The live Logiwa sandbox is unavailable; use references/logiwa-spec/*.md instead of opening my.logiwa.com. Close every browser tab you open before finishing.`
    let b = await throttled(prompt, { label: `${m.code}-fix-r${round}`, phase: 'Audit', schema: BUILD_SCHEMA })
    if (!b) b = await throttled(prompt + '\n(Retry after an errored attempt.)', { label: `${m.code}-fix-r${round}-retry`, phase: 'Audit', schema: BUILD_SCHEMA })
    if (!b) { log(`${m.code}: builder failed twice in round ${round}; stopping this module`); return { id: m.id, code: m.code, wowed: false, rounds: round, critique, error: 'builder failed' } }
    if (b.requestsFiled) {
      const p = await runPatch(`${m.code} audit round ${round}`)
      if (p && p.applied && p.applied.length) {
        await throttled(`${m.code} "${m.id}": the F-patch agent applied your shared-file requests:\n${p.applied.map(x => '- ' + x).join('\n')}\nRejected:\n${(p.rejected || []).map(x => '- ' + x).join('\n') || '- none'}\nWire the real shared interfaces, re-verify, update docs/progress/${m.id}.md. Close any browser tab you open.\n${MODULE_RULES}`,
          { label: `${m.code}-wire-r${round}`, phase: 'Audit', schema: BUILD_SCHEMA })
      }
    }
  }
  log(`${m.code}: not wowed after ${ROUNDS} audit rounds`)
  return { id: m.id, code: m.code, wowed: false, rounds: ROUNDS, critique: last }
}

phase('Audit')
const results = (await pipeline(MODULES, m => auditModule(m))).filter(Boolean)
await runPatch('final sweep')

phase('Gate')
const gate = await throttled(`You are the release gate for KitStaks WMS after the audit rounds. All module agents are finished; you may edit any file to fix errors with minimal, correct changes (never weaken tests or disable lint rules).
Run, fix, and re-run until green: npm run lint; node scripts/tc-queue.mjs (whole project); npm test; npm run db:verify. Some foundation tests (tests/unit/foundation/domain) assert features are still "not configured yet" stubs that modules have since built — update those assertions to the real behaviour rather than reverting code. Then run "npx next build" (the dev server on :3000 must keep running: if the build conflicts with .next, restart it afterwards with "npx next dev -p 3000"). List any route still rendering ModulePlaceholder / data-placeholder-module.
${MODULE_RULES.replace('Never run next build.', '')}`,
  { label: 'gate', phase: 'Gate', schema: {
    type: 'object',
    properties: {
      lint: { type: 'string' }, typecheck: { type: 'string' }, tests: { type: 'string' }, dbVerify: { type: 'string' }, build: { type: 'string' },
      placeholdersRemaining: { type: 'array', items: { type: 'string' } }, notes: { type: 'string' },
    },
    required: ['lint', 'typecheck', 'tests', 'dbVerify', 'build', 'placeholdersRemaining', 'notes'],
  } })

return {
  modules: results.map(r => ({ code: r.code, id: r.id, wowed: r.wowed, rounds: r.rounds, error: r.error, scores: r.critique?.scores, failures: r.critique?.functional_failures, specGaps: r.critique?.logiwa_wins })),
  notWowed: results.filter(r => !r.wowed).map(r => r.code),
  gate,
}